require "csv"

class WeeklyWorkoutExport
  def initialize(member, week_start)
    @member = member
    @week_start = week_start
  end

  def export
    CSV.generate do |csv|
      csv << %w[date exercise sets reps]
      rows.each { |row| csv << row }
    end
  end

  private

  def rows
    @member.workouts.where(performed_on: @week_start...(@week_start + 7)).order(:performed_on)
      .map { |workout| [ workout.performed_on, workout.exercise, workout.sets, workout.reps ] }
  end
end

