require "csv"

class WeeklyWorkoutExport
  FORMATTERS = {
    "csv" => ->(rows) { CSV.generate { |csv| rows.each { |row| csv << row } } },
    "tsv" => ->(rows) { rows.map { |row| row.join("\t") }.join("\n") }
  }.freeze

  def initialize(member, week_start, format: "csv")
    @member = member
    @week_start = week_start
    @formatter = FORMATTERS.fetch(format)
  end

  def export
    @formatter.call([ %w[date exercise sets reps] ] + rows)
  end

  private

  def rows
    @member.workouts.where(performed_on: @week_start...(@week_start + 7)).order(:performed_on)
      .map { |workout| [ workout.performed_on, workout.exercise, workout.sets, workout.reps ] }
  end
end
